void ShellController::start_calibration(const std::string& printer, const std::string& filament)
{
    Agent::AgentHost& host = m_agent_pane->web_view().host();
    // The assistant chooses and makes the test, so without it the row leads
    // to its setup instead.
    if (host.availability() != Agent::AgentAvailability::Ready) {
        offer_agent_setup(_L("The AI assistant isn't set up yet. Set it up in the chat panel, and it can choose a "
                             "calibration test and read the print with you."));
        return;
    }
    // A menu row has no sentence of the assistant's before it, so the dialog
    // says what the assistant would: the open project closes, and the test's
    // settings are temporary. Which test is the assistant's question.
    const wxString project = from_u8(m_workspace->snapshot().setup.project_name);
    const wxString target  = filament.empty() ?
                                 wxString::Format(_L("on %s"), from_u8(printer)) :
                                 wxString::Format(_L("for %1$s on %2$s"), from_u8(filament), from_u8(printer));
    MessageDialog dialog(m_frame,
                         wxString::Format(_L("The assistant will ask which test fits what you are seeing. When the test "
                                             "starts, %1$s is saved and closed, and a new project opens with the test %2$s. "
                                             "Settings the test changes are temporary and are not saved to your filament "
                                             "until you choose a result."),
                                          project, target),
                         _L("Start a calibration test?"), wxYES_NO | wxYES_DEFAULT);
    dialog.SetButtonLabel(wxID_YES, _L("Start test"));
    dialog.SetButtonLabel(wxID_NO, _L("Cancel"));
    if (dialog.ShowModal() != wxID_YES)
        return;

    // The project chat, not the printer's: the test needs the project's tools.
    restore_task_panel();
    if (m_tabpanel->GetSelection() == MainFrame::tpHome)
        m_frame->select_tab(size_t(MainFrame::tp3DEditor));
    m_agent_pane_user_collapsed = false;
    set_agent_pane_collapsed(false);
    // The person's own words, saying what they just agreed to, so the
    // calibration skill takes over without asking it again.
    const wxString asked = filament.empty() ? wxString::Format(_L("Calibrate a filament on %s."), from_u8(printer)) :
                                              wxString::Format(_L("Calibrate %1$s on %2$s."), from_u8(filament), from_u8(printer));
    const wxString text  = asked + " " + wxString::Format(_L("I'm fine with %s being saved and closed for the test."), project);
    const std::string id = "calibrate-" + std::to_string(std::chrono::steady_clock::now().time_since_epoch().count());
    std::string refusal;
    if (host.submit_issue_message(id, into_u8(text), {}, &refusal) == Agent::AgentHost::SubmitResult::Refused)
        show_error(m_frame, _L("The chat could not take the request right now. Try again in a moment."));
}

