rep(`    bool assistant_reply_complete(const std::string& text)
    {`, `    // The three Calibrate… rows. A row asks first in OrcaSlicer's dialog,
    // since the test will close the open project: Cancel there changes
    // nothing, and Start test sends the request to the project chat as the
    // person's own words. The stand-in assistant then asks which test, and
    // the tapped answer makes it in a project of its own.
    static constexpr const char* kCalibrationPrinter = "Workshop X1C";
    static constexpr const char* kCalibrationProject = "Backpack hook";

    // The next modal dialog, drawn with the window behind it and answered.
    void answer_next_dialog(const std::string& name, int answer)
    {
        m_dialog_seen.clear();
        m_dialog_timer = std::make_unique<wxTimer>();
        m_dialog_timer->Bind(wxEVT_TIMER, [this, name, answer](wxTimerEvent&) {
            for (wxWindow* window : wxTopLevelWindows)
                if (auto* dialog = dynamic_cast<wxDialog*>(window); dialog != nullptr && dialog->IsModal()) {
                    m_dialog_timer->Stop();
                    std::function<void(wxWindow*)> read = [&](wxWindow* parent) {
                        for (wxWindow* child : parent->GetChildren()) {
                            if (dynamic_cast<wxStaticText*>(child) != nullptr)
                                m_dialog_seen += ui_text(child->GetLabel()) + "\\n";
                            read(child);
                        }
                    };
                    m_dialog_seen = ui_text(dialog->GetTitle()) + "\\n";
                    read(dialog);
                    std::cout << "HARNESS CALIBRATION DIALOG " << name << " " << m_dialog_seen << std::endl;
                    blit_screen(m_frame->GetScreenRect(), name + "-window");
                    blit_screen(dialog->GetScreenRect(), name);
                    dialog->EndModal(answer);
                    return;
                }
        });
        m_dialog_timer->Start(300);
    }

    // What a cancelled dialog must have left as it was.
    struct CalibrationBefore
    {
        std::uint64_t session{0};
        std::size_t   messages{0};
    };
    CalibrationBefore calibration_before() const
    {
        return {m_workspace_adapter().snapshot().session.value(), installed_shell()->agent_pane()->web_view().host().conversation().size()};
    }
    void check_untouched(const CalibrationBefore& before, const std::string& name)
    {
        check(m_workspace_adapter().snapshot().session.value() == before.session &&
                  m_workspace_adapter().snapshot().setup.project_name == kCalibrationProject,
              name + "_cancel_keeps_the_project");
        check(installed_shell()->agent_pane()->web_view().host().conversation().size() == before.messages,
              name + "_cancel_sends_nothing");
    }
    Workspace::IWorkspace& m_workspace_adapter() const { return *installed_shell()->workspace(); }

    void begin_calibration_capture()
    {
        // A saved printer, so Home has a card for it and the chip names it.
        SetupCommands::select_printer_preset(*m_plater, kSetupFixturePrinter);
        Printers::add_named_printer(*m_plater, kCalibrationPrinter, {});
        check(SetupCommands::select_named_printer(*m_plater, kCalibrationPrinter), "calibration_printer_selected");
        m_plater->set_project_name(wxString::FromUTF8(kCalibrationProject));
        m_frame->select_tab(size_t(MainFrame::tp3DEditor));
