// Turns on the fake Bambu printer in a JusPrin2.conf (Testing/README.md),
// keeping the trailing MD5 line valid the way AppConfig writes it.
const fs = require('fs');
const crypto = require('crypto');
const path = process.argv[2];
const text = fs.readFileSync(path, 'utf8');
const end = text.lastIndexOf('}');
const config = JSON.parse(text.slice(0, end + 1));
config.jusprin = Object.assign({}, config.jusprin, { fake_printer: true });
if (config.app) config.app.single_instance = false;
const body = JSON.stringify(config, null, 4);
const md5 = crypto.createHash('md5').update(body).digest('hex').toUpperCase();
fs.writeFileSync(path, body + '\n# MD5 checksum ' + md5 + '\n');
console.log('jusprin =', JSON.stringify(config.jusprin), 'printer =', config.presets && config.presets.machine);

// Drives calibration_generate and the settings tools end to end over MCP,
// through the bundled stdio bridge, as an external client would. Usage:
//   node mcp-calibration.mjs <jusprin-mcp.exe> <discovery mcp.json> <transcript.jsonl>
import { spawn } from 'node:child_process';
import { createInterface } from 'node:readline';
import { writeFileSync, appendFileSync } from 'node:fs';

const [bridgePath, discovery, transcript] = process.argv.slice(2);
writeFileSync(transcript, '');
const bridge = spawn(bridgePath, ['--discovery', discovery], { stdio: ['pipe', 'pipe', 'inherit'] });
const waiting = new Map();
createInterface({ input: bridge.stdout }).on('line', (line) => {
  const message = JSON.parse(line);
  if (message.id !== undefined && waiting.has(message.id)) {
    waiting.get(message.id)(message);
    waiting.delete(message.id);
  }
});
let next = 1;
function rpc(method, params = {}) {
  const id = next++;
  bridge.stdin.write(JSON.stringify({ jsonrpc: '2.0', id, method, params }) + '\n');
  return new Promise((resolve) => waiting.set(id, resolve));
}
const failures = [];
function check(ok, name) {
  console.log(`${ok ? 'PASS' : 'FAIL'} ${name}`);
  if (!ok) failures.push(name);
}
async function call(name, args = {}) {
  const message = await rpc('tools/call', { name, arguments: args });
  const result = message.result ?? {};
  const content = result.structuredContent ?? {};
  appendFileSync(transcript, JSON.stringify({ tool: name, arguments: args, isError: !!result.isError, result: content }) + '\n');
  return { error: result.isError ? content.error ?? content : null, content };
}
