const listOf = (current, value) => String(current).split(',').map(() => value).join(',');

const init = await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'calibration-e2e', version: '1' } });
bridge.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
check(!!init.result, 'initialized over the stdio bridge');

