}
const generate = tools.find((tool) => tool.name === 'calibration_generate');
check(!!generate, 'calibration_generate is offered over MCP');
console.log('annotations', JSON.stringify(generate?.annotations));

const printers = await call('printer_list');
console.log('printers', JSON.stringify(printers.content.items));
const before = await call('workspace_inspect', { sections: ['summary', 'printer'] });
console.log('before', JSON.stringify(before.content).slice(0, 600));

// A range Orca's dialog refuses closes nothing.
