check(refused.error?.code === 'invalid_argument', 'a refused range is refused: ' + refused.error?.message);

// The temperature tower.
const tower = await call('calibration_generate', { test: 'temperature', start: 230, end: 190, projectName: 'Temperature test' });
check(!tower.error && tower.content.projectName === 'Temperature test', 'temperature tower generated');
