let preview = await call('settings_preview_patch', { scope: 'filament', target, changes, persistAs: copy });
check(preview.content.valid === true, 'the calibrated copy previews: ' + JSON.stringify(preview.content.issues ?? []));
let applied = await call('settings_apply_patch', { scope: 'filament', target, changes, persistAs: copy,
  expectedSessionId: preview.content.sessionId, expectedRevision: preview.content.revision });
check(!applied.error && applied.content.savedAs === copy, 'saved as ' + copy + ' ' + JSON.stringify(applied.error ?? ''));

// A second result under the same name updates that copy.
const own = { preset: copy };
const again = { nozzle_temperature: listOf(current, '220') };
preview = await call('settings_preview_patch', { scope: 'filament', target: own, changes: again, persistAs: copy });
applied = await call('settings_apply_patch', { scope: 'filament', target: own, changes: again, persistAs: copy,
