const pa = await call('calibration_generate', { test: 'pressure_advance', projectName: 'Pressure advance test' });
check(!pa.error && pa.content.applied?.method === 'tower' && pa.content.applied?.end === 0.1, 'pressure-advance tower generated with the dialog defaults');
