        m_persistence->attach();
        m_autosave = std::make_unique<Workspace::ProjectAutosave>(
            *plater, *m_persistence, *m_workspace,
            std::filesystem::path(data_dir()) / "jusprin" / "projects");
        auto& project_host = m_agent_pane->web_view().host();
