// --calibration-capture: a model that asks which test a Calibrate… row's
// request wants, makes the temperature tower when told, and opens the test's
// own chat with what to print and photograph.
class CalibrationAgent final : public Agent::IAgentService
{
public:
    static constexpr const char* kQuestion =
        "Happy to. For a filament you haven't tuned yet, start with a temperature tower: it finds the temperature that "
        "prints cleanest. Flow and pressure advance come after it.\n"
        "Choices: Temperature | Flow | Pressure advance";
    static constexpr const char* kAnswer = "Temperature";
    static constexpr const char* kFirstMessage =
        "Your temperature tower is ready: blocks from 230 °C at the bottom to 190 °C at the top. Print it, then "
        "photograph the side with the numbers, in light from one side, and send the photo here.";

    bool ready() const override { return true; }
    bool busy() const override { return m_active; }
    bool start(const Agent::AgentRequest& request) override
    {
        m_active = true;
        if (request.purpose == Agent::AgentRequest::Purpose::ConversationTitle)
            m_events.push_back(Agent::AgentEvent::delta("Calibration"));
        else if (request.user_text == kAnswer) {
            const nlohmann::json arguments{{"test", "temperature"}, {"start", 230}, {"end", 190}, {"projectName", "Temperature test"}};
            m_events.push_back(Agent::AgentEvent::tool_call({"call-1", Agent::ToolRequest{"calibration_generate", arguments.dump()}, true}));
            return true;
        } else
            m_events.push_back(Agent::AgentEvent::delta(request.user_text.rfind("JusPrin app note", 0) == 0 ? kFirstMessage : kQuestion));
        m_events.push_back(Agent::AgentEvent::completed());
        return true;
    }
    bool continue_after_tool(const Agent::AgentToolResult&) override
    {
        m_events.push_back(Agent::AgentEvent::completed());
        return true;
    }
    void cancel() override
    {
        m_active = false;
        m_events.clear();
    }
    std::optional<Agent::AgentEvent> poll() override
    {
        if (m_events.empty())
            return std::nullopt;
        Agent::AgentEvent event = std::move(m_events.front());
        m_events.pop_front();
        if (event.kind == Agent::AgentEventKind::Completed || event.kind == Agent::AgentEventKind::Failed)
            m_active = false;
        return event;
    }

private:
    std::deque<Agent::AgentEvent> m_events;
    bool                          m_active{false};
};

