param([string]$Match, [string]$Out, [int]$TimeoutSeconds = 600, [string]$Process = 'shell_integration_harness')
# Waits for a visible top-level window of the process whose title contains
# $Match and prints it with PrintWindow (PW_RENDERFULLCONTENT) from a
# DPI-aware process, which draws it even when other windows cover it.
Add-Type -AssemblyName System.Drawing
Add-Type @"
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Text;
public static class Dlg {
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left, Top, Right, Bottom; }
  public delegate bool EnumProc(IntPtr h, IntPtr p);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc f, IntPtr p);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowTextW(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern bool PrintWindow(IntPtr h, IntPtr dc, uint flags);
  [DllImport("user32.dll")] public static extern bool SetProcessDPIAware();
  public static List<KeyValuePair<IntPtr,string>> Windows(uint pid) {
    var found = new List<KeyValuePair<IntPtr,string>>();
    EnumWindows((h, p) => { uint owner; GetWindowThreadProcessId(h, out owner);
      if (owner == pid && IsWindowVisible(h)) { var s = new StringBuilder(512); GetWindowTextW(h, s, 512); found.Add(new KeyValuePair<IntPtr,string>(h, s.ToString())); }
      return true; }, IntPtr.Zero);
    return found;
  }
}
"@
[Dlg]::SetProcessDPIAware() | Out-Null
$deadline = (Get-Date).AddSeconds($TimeoutSeconds)
$h = [IntPtr]::Zero; $seen = @{}
while ($h -eq [IntPtr]::Zero -and (Get-Date) -lt $deadline) {
  Start-Sleep -Milliseconds 200
  foreach ($p in Get-Process -Name $Process -ErrorAction SilentlyContinue) {
    foreach ($w in [Dlg]::Windows([uint32]$p.Id)) {
      if (-not $seen.ContainsKey($w.Value)) { $seen[$w.Value] = 1; "seen '$($w.Value)'" }
      if ($w.Value -like "*$Match*") { $h = $w.Key }
    }
  }
}
if ($h -eq [IntPtr]::Zero) { "no window matching '$Match'"; exit 1 }
Start-Sleep -Milliseconds 1200
$r = New-Object Dlg+RECT
[Dlg]::GetWindowRect($h, [ref]$r) | Out-Null
$bmp = New-Object System.Drawing.Bitmap ($r.Right - $r.Left), ($r.Bottom - $r.Top)
$g = [System.Drawing.Graphics]::FromImage($bmp)
$dc = $g.GetHdc()
[Dlg]::PrintWindow($h, $dc, 2) | Out-Null
$g.ReleaseHdc($dc)
$bmp.Save($Out, [System.Drawing.Imaging.ImageFormat]::Png)
"saved $Out $($bmp.Width)x$($bmp.Height)"

