// Typed view of the jusprin-agent-bridge protocol. The canonical shared
// source is resources/jusprin/agent/protocol.json; the constants here are
// derived from it at build time so the page and the native host cannot
// silently disagree about the protocol name or version.

import protocolJson from '@resources/jusprin/agent/protocol.json';

export const PROTOCOL_NAME: string = protocolJson.name;
export const PROTOCOL_VERSION: number = protocolJson.version;
export const PAGE_CAPABILITIES: string[] = protocolJson.capabilities;

export type PageMessageType =
  | 'hello'
  | 'state_request'
  | 'user_message'
  | 'stop_generation'
  | 'retry_message'
  | 'tool_cancel'
  | 'work_cancel'
  | 'create_conversation'
  | 'switch_conversation'
  | 'restore_conversation'
  | 'rename_conversation'
  | 'delete_conversation'
  | 'draft_update'
  | 'attach_file'
  | 'remove_attachment'
  | 'setup_check_key'
  | 'setup_cancel'
  | 'mcp_catalog'
  | 'mcp_preview'
  | 'mcp_connect'
  | 'reveal_path'
  | 'pick_attachment'
  | 'set_chat_model'
  | 'printer_action'
  | 'printer_instructions'
  | 'printer_opening'
  | 'filament_instructions'
  | 'shell_action'
  | 'project_instructions'
  | 'skills'
  | 'settings_catalog_request'
  | 'settings_action';

export type HostMessageType =
  | 'hello_ack'
  | 'hello_reject'
  | 'state'
  | 'conversations_updated'
  | 'context'
  | 'appearance'
  | 'agent_status'
  | 'message_added'
  | 'assistant_started'
  | 'assistant_delta'
  | 'assistant_completed'
  | 'assistant_failed'
  | 'assistant_stopped'
  | 'tool_activity'
  | 'bridge_error'
  | 'attachment_updated'
  | 'setup_status'
  | 'mcp_catalog'
  | 'mcp_preview'
  | 'mcp_status'
  | 'change_added'
  | 'work_updated'
  | 'open_setup'
  | 'model_catalog'
  | 'chat_model'
  | 'printer_session'
  | 'settings_catalog';

export interface Envelope<T = unknown> {
  protocol: string;
  version: number;
  id: string;
  type: string;
  correlationId?: string;
  sessionId?: string;
  revision?: number;
  payload: T;
}

// 'note' is the host's own voice: a short factual line the native shell posts
// when it changes something the reader should see in the thread (a filament
// change, for example). It is never a turn -- no reply follows it, and the host never
// sends it to the model -- so it renders as a plain line, not a bubble.
export type MessageRole = 'user' | 'assistant' | 'note';
export type MessageStateName = 'complete' | 'streaming' | 'failed' | 'stopped';
export type AgentStatus = 'ready' | 'unavailable';
export type Appearance = 'light' | 'dark';

export interface AgentErrorInfo {
  code: string;
  message: string;
  retryable: boolean;
}

export interface WireMessage {
  id: string;
  role: MessageRole;
  state: MessageStateName;
  text: string;
  attempt: number;
  clientMessageId?: string;
  inReplyTo?: string;
  // The host's stamp when the message was stored, RFC 3339. Absent from
  // messages of documents written before it was sent; the thread then draws
  // a turn's activity line without its elapsed time.
  createdAt?: string;
  error?: AgentErrorInfo;
  attachments?: string[]; // sent attachment IDs, resolved against StatePayload.attachments
  swatch?: string; // notes: a colour, '#RRGGBB', that leads the line
  // Notes: what the app knows once a file the person brought in has loaded.
  // The model reads it; the page draws it only as a card, when the Agent
  // could not speak about it (fileReportCard).
  fileReport?: FileReport;
  fileReportCard?: boolean;
  // User messages sent from a print-issue bubble on the canvas: the issue,
  // its target and the freshness of the evidence, for the model. The page
  // draws the message's text and nothing from here.
  issueContext?: unknown;
}

// Raw words shown or scheduled by Orca during opening, and the app's answer
// when there was a dialog. An empty answer belongs to a notification or error.
export interface OrcaMessage {
  source?: 'dialog' | 'notification' | 'error' | 'app';
  title: string;
  text: string;
  buttons: ('ok' | 'yes' | 'no' | 'cancel')[];
  answer: 'ok' | 'yes' | 'no' | 'cancel' | '';
  recognized?: false; // present only for a dialog the app did not know how to answer
}

interface LoadSelectedSetup {
  printerPreset: string;
  filamentPreset: string;

