   Sheet (24 padding, 16 between its parts). */
.printer-dialog-shade {
  position: fixed;
  inset: 0;
  z-index: 4;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 48px 16px 16px;
  background: color-mix(in srgb, var(--overlay-scrim) var(--printer-dialog-scrim), transparent);
}

.printer-dialog {
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: 100%;
  max-width: var(--printer-dialog-width);
  padding: 24px;
  background: var(--surface-raised);
  border-radius: var(--printer-dialog-radius);
  box-shadow: var(--elevation-strong);
}

.printer-dialog h2 {
  margin: 0;
  font: var(--font-section);
  color: var(--text-primary);
}

.printer-dialog p {
  margin: 0;
  overflow-wrap: anywhere;
  font: var(--font-body);
  color: var(--text-secondary);
}

.printer-dialog p[role='alert'] {
